// SPDX-License-Identifier: MIT
pragma solidity 0.8.9;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/BetBitcoinAi.sol";

contract MockRouter {
    function factory() external pure returns (address) {
        return address(0x1234567890123456789012345678901234567890);
    }

    function WETH() external pure returns (address) {
        return address(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
    }
}

contract MockFactory {
    function createPair(address, address) external pure returns (address) {
        return address(0x1111111111111111111111111111111111111111);
    }
}

contract MockWETH {}

contract BetBitcoinAiTest is Test {
    BetBitcoinAi token;
    address owner = makeAddr("owner");
    address user = makeAddr("user");

    function setUp() public {
        // Deploy and mock necessary Uniswap contracts
        MockRouter mockRouter = new MockRouter();
        MockFactory mockFactory = new MockFactory();
        MockWETH mockWETH = new MockWETH();

        // Etch contracts to expected addresses
        vm.etch(address(0x10ED43C718714eb63d5aA57B78B54704E256024E), address(mockRouter).code);
        vm.etch(address(0x1234567890123456789012345678901234567890), address(mockFactory).code);
        vm.etch(address(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2), address(mockWETH).code);

        vm.startPrank(owner);
        token = new BetBitcoinAi();
        token.transfer(user, 1000 * 10 ** token.decimals());
        vm.stopPrank();
    }

    function test_swapTrading_causes_99PercentFee() public {
        uint256 transferAmount = 100 * 10 ** token.decimals();
        address recipient = makeAddr("recipient");

        // User's initial balances
        uint256 userBalanceBefore = token.balanceOf(user);
        uint256 recipientBalanceBefore = token.balanceOf(recipient);

        // Owner enables high-fee period
        vm.startPrank(owner);
        token.swapTrading(); // Sets tax period to next 2 blocks
        vm.stopPrank();

        // Move to next block (still in high-fee period)
        vm.roll(block.number + 1);

        // User makes transfer during high-fee period
        vm.prank(user);
        token.transfer(recipient, transferAmount);

        // Calculate expected fee and received amount (99% fee)
        uint256 expectedFee = transferAmount * 99 / 100;
        uint256 expectedReceived = transferAmount - expectedFee;

        // Check balances after transfer
        uint256 userBalanceAfter = token.balanceOf(user);
        uint256 recipientBalanceAfter = token.balanceOf(recipient);

        // User pays full amount (should lose 100 tokens)
        assertEq(userBalanceAfter, userBalanceBefore - transferAmount, "User should pay full transfer amount");

        // Recipient only receives 1% of tokens (1 token)
        assertEq(
            recipientBalanceAfter - recipientBalanceBefore,
            expectedReceived,
            "Recipient should only receive 1% of transferred tokens during high-fee period"
        );
    }
}
