    }
}

contract MockWETH {}

contract BetBitcoinAiTest is Test {
    BetBitcoinAi token;
    address owner = makeAddr("owner");
    address user = makeAddr("user");

    function setUp() public {
        // Deploy and mock necessary Uniswap contracts
        MockRouter mockRouter = new MockRouter();
        MockFactory mockFactory = new MockFactory();
        MockWETH mockWETH = new MockWETH();

        // Etch contracts to expected addresses
        vm.etch(address(0x10ED43C718714eb63d5aA57B78B54704E256024E), address(mockRouter).code);
        vm.etch(address(0x1234567890123456789012345678901234567890), address(mockFactory).code);
        vm.etch(address(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2), address(mockWETH).code);

        vm.startPrank(owner);
        token = new BetBitcoinAi();
        token.transfer(user, 1000 * 10 ** token.decimals());
        vm.stopPrank();
    }

    function test_swapTrading_causes_99PercentFee() public {
        uint256 transferAmount = 100 * 10 ** token.decimals();
        address recipient = makeAddr("recipient");

        // === PRE-TRIGGER STATE CAPTURE ===
        console.log("--- BEFORE-Trigger State ---");
        uint256 preTriggerRecipientBal = token.balanceOf(recipient);
        uint256 preTriggerMarketingFees = token.tokensForMarketing();
        uint256 preTriggerLiquidityFees = token.tokensForLiquidity();
        console.log("Pre-trigger recipient balance:", preTriggerRecipientBal);
        console.log("Pre-trigger marketing fees:", preTriggerMarketingFees);
        console.log("Pre-trigger liquidity fees:", preTriggerLiquidityFees);

        // PRE-TRIGGER TRANSFER
        uint256 userBalancePre = token.balanceOf(user);
        vm.prank(user);
        token.transfer(recipient, transferAmount);

        uint256 actualReceivedPre = token.balanceOf(recipient) - preTriggerRecipientBal;
        uint256 actualFeeAccumulatedPre = (token.tokensForMarketing() - preTriggerMarketingFees) + 
                                       (token.tokensForLiquidity() - preTriggerLiquidityFees);
        console.log("Pre-trigger transfer: recipient received %s tokens", actualReceivedPre);
        console.log("Accumulated fees during normal period:", actualFeeAccumulatedPre);

        // === TRIGGER ACTION ===
        console.log("--- TRIGGER: swapTrading() called ---");
        vm.startPrank(owner);
        token.swapTrading(); // Sets tax period to next 2 blocks
        vm.stopPrank();
        vm.roll(block.number + 1); // Move to next block

        // === POST-TRIGGER STATE CAPTURE ===
        console.log("--- AFTER-Trigger State ---");
        uint256 postTriggerRecipientBal = token.balanceOf(recipient);
        uint256 postTriggerMarketingFees = token.tokensForMarketing();
        uint256 postTriggerLiquidityFees = token.tokensForLiquidity();

        // POST-TRIGGER TRANSFER
        uint256 userBalancePost = token.balanceOf(user);
        vm.prank(user);
        token.transfer(recipient, transferAmount);

        uint256 actualReceivedPost = token.balanceOf(recipient) - postTriggerRecipientBal;
        uint256 actualFeeAccumulatedPost = (token.tokensForMarketing() - postTriggerMarketingFees) + 
                                        (token.tokensForLiquidity() - postTriggerLiquidityFees);

        console.log("Post-trigger transfer: recipient received %s tokens", actualReceivedPost);
        console.log("Accumulated fees during high-fee period:", actualFeeAccumulatedPost);

        // === CALCULATE FEE DIFFERENCES ===
        uint256 preFeePercentage = 100 - (actualReceivedPre * 100 / transferAmount);
        uint256 postFeePercentage = 100 - (actualReceivedPost * 100 / transferAmount);
        console.log("Effective fee pre-trigger:", preFeePercentage, "%");
        console.log("Effective fee post-trigger:", postFeePercentage, "%");

        // === FINAL VERIFICATION ===
        bool vulnerabilityExists = 
            postFeePercentage > 95 &&            // 99% fee expected
            (postFeePercentage > preFeePercentage * 10); // >10x fee increase

        if (vulnerabilityExists) {
            console.log("Vulnerability Exists: Fee increased from", preFeePercentage, 
                      "% to", postFeePercentage, "% (>95%) after swapTrading call");
        } else {
            console.log("Vulnerability not Exist: Fee remained at", postFeePercentage, 
                      "% (<95% threshold) after swapTrading call");
        }

        // Check balances after final transfer
        uint256 userBalanceAfter = token.balanceOf(user);
        uint256 recipientBalanceAfter = token.balanceOf(recipient);

        assertEq(userBalanceAfter, userBalancePost - transferAmount, "User should pay full transfer amount");
        assertEq(
            recipientBalanceAfter - postTriggerRecipientBal,
            actualReceivedPost,
            "Recipient received amount doesn't match actual transfer"
        );
    }
}
